import { memo, useState } from 'react';
import { StyleSheet, Text, View, useWindowDimensions } from 'react-native';
import FastImage from 'react-native-fast-image';
import type { Post } from '../data/posts';

export const rowHeight = (fontScale: number): number => 208 + Math.ceil(24 * fontScale);

function Thumbnail({ uri, title }: { uri: string; title: string }): JSX.Element {
  const [failed, setFailed] = useState(false);
  return failed ? (
    <View style={styles.image}><Text>Image unavailable</Text></View>
  ) : (
    <FastImage
      style={styles.image}
      source={{ uri, cache: FastImage.cacheControl.web }}
      resizeMode={FastImage.resizeMode.cover}
      accessibilityLabel={title}
      onError={() => setFailed(true)}
    />
  );
}

export const FeedRow = memo(function FeedRow({ item }: { item: Post }): JSX.Element {
  const { fontScale } = useWindowDimensions();
  return (
    <View style={[styles.row, { height: rowHeight(fontScale) }]}>
      <Thumbnail key={item.imageUrl} uri={item.imageUrl} title={item.title} />
      <Text style={styles.caption} numberOfLines={1} accessibilityLabel={item.title}>{item.title}</Text>
    </View>
  );
});

const styles = StyleSheet.create({
  // shortcut: fixed rows truncate long captions; use measured rows for expanded captions.
  row: { padding: 8 },
  caption: { fontSize: 16, lineHeight: 24 },
  image: { width: '100%', height: 192, borderRadius: 8, justifyContent: 'center', alignItems: 'center' },
});

import { useCallback } from 'react';
import { FlatList, SafeAreaView, StyleSheet, Text, useWindowDimensions } from 'react-native';
import type { ListRenderItemInfo } from 'react-native';
import { FeedRow, rowHeight } from '../components/FeedRow';
import { posts } from '../data/posts';
import type { Post } from '../data/posts';

const keyExtractor = (item: Post): string => item.id;
const renderItem = ({ item }: ListRenderItemInfo<Post>): JSX.Element => <FeedRow item={item} />;

export function FeedScreen(): JSX.Element {
  const { fontScale } = useWindowDimensions();
  const height = rowHeight(fontScale);
  const getItemLayout = useCallback((_data: ArrayLike<Post> | null | undefined, index: number) => ({
    length: height, offset: height * index, index,
  }), [height]);
  return (
    <SafeAreaView style={styles.screen}>
      <FlatList
        data={posts}
        extraData={fontScale}
        keyExtractor={keyExtractor}
        renderItem={renderItem}
        getItemLayout={getItemLayout}
        initialNumToRender={8}
        maxToRenderPerBatch={10}
        ListEmptyComponent={<Text>No images yet.</Text>}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({ screen: { flex: 1 } });
